<?php
session_start();
require_once __DIR__ . '/conexion.php';
if (empty($_SESSION['id_usuario']) || ($_SESSION['rol'] ?? '') !== 'administrador') { http_response_code(403); exit('Acceso restringido.'); }
function h($v) { return htmlspecialchars((string)($v ?? ''), ENT_QUOTES, 'UTF-8'); }
if (empty($_SESSION['csrf_tm'])) $_SESSION['csrf_tm'] = bin2hex(random_bytes(32));
function check_post() { if (!hash_equals($_SESSION['csrf_tm'], (string)($_POST['csrf'] ?? ''))) { http_response_code(403); exit('Solicitud inválida'); } }
function num_id($v) { $x=filter_var($v,FILTER_VALIDATE_INT); return $x && $x>0 ? (int)$x : null; }
function opt_id($v) { return ($v === '' || $v === null) ? null : num_id($v); }
function choices($sql) { global $conexion; return $conexion->query($sql)->fetchAll(PDO::FETCH_ASSOC); }
function dt($v) { if (!$v) return null; $d=DateTimeImmutable::createFromFormat('!Y-m-d\TH:i', $v); return $d && $d->format('Y-m-d\TH:i') === $v ? $d->format('Y-m-d H:i:s') : false; }
$error='';
$success=isset($_GET['ok']);
$buses=choices("SELECT b.id_bus,b.codigo,b.id_linea,l.nombre AS linea FROM buses b LEFT JOIN lineas l ON l.id_linea=b.id_linea ORDER BY b.codigo");
if ($_SERVER['REQUEST_METHOD']==='POST') { check_post();
 $bus=num_id($_POST['bus']??null); $inicio=dt($_POST['inicio']??''); $fin=dt($_POST['fin']??''); $estado=$_POST['estado']??'';
 if (!$bus || !$inicio || $fin===false || ($fin && $fin<$inicio) || !in_array($estado,['programado','en_curso','finalizado'],true)) $error='Revisa los datos y fechas.';
 else { try {
  $s=$conexion->prepare('SELECT id_linea FROM buses WHERE id_bus=?');$s->execute([$bus]);$linea=$s->fetchColumn();
  if (!$linea) $error='El bus debe estar asignado a una línea antes de crear un recorrido.';
  else { $s=$conexion->prepare('INSERT INTO recorridos(id_bus,id_linea,inicio,fin,estado) VALUES (?,?,?,?,?)');$s->execute([$bus,$linea,$inicio,$fin,$estado]);header('Location: recorridos_buses.php?ok=1');exit; }
 } catch (PDOException $e) {error_log($e->getMessage());$error='No se pudo registrar el recorrido.';} }
}
$rows=choices("SELECT r.*,b.codigo,l.nombre AS linea FROM recorridos r JOIN buses b ON b.id_bus=r.id_bus JOIN lineas l ON l.id_linea=r.id_linea ORDER BY r.id_recorrido DESC LIMIT 150");
?>
<!doctype html><html lang="es"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Recorridos de buses · Transmetro</title><link href="https://cdn.jsdelivr.net/npm/bootstrap@5.3.3/dist/css/bootstrap.min.css" rel="stylesheet"><style>body{background:#f5f7fb;color:#1c2d45}.navbar{background:#14253e}.card{border:0;border-radius:18px;box-shadow:0 8px 25px #152e4a13}.btn-brand{background:#f0a72e;font-weight:700}.table{font-size:.91rem}</style></head><body><nav class="navbar navbar-dark"><div class="container"><a class="navbar-brand fw-bold" href="panel.php">Transmetro Info</a><a class="btn btn-outline-light btn-sm" href="panel.php">Volver al panel</a></div></nav><main class="container py-5"><h1 class="h2 fw-bold">Recorridos de buses</h1><p class="text-secondary">Proyecto académico · Datos de demostración</p><?php if ($success): ?><div class="alert alert-success">Registro guardado correctamente.</div><?php endif; ?><?php if ($error): ?><div class="alert alert-danger"><?=h($error)?></div><?php endif; ?><div class="card mb-4"><div class="card-body p-4"><h2 class="h5">Nuevo registro</h2><form method="post" class="row g-3"><input type="hidden" name="csrf" value="<?=h($_SESSION['csrf_tm'])?>"><div class="col-md-6"><label class="form-label">Bus asignado a línea</label><select class="form-select" name="bus" required><option value="">Seleccionar</option><?php foreach ($buses as $v): ?><option value="<?=h($v['id_bus'])?>"><?=h($v['codigo'])?></option><?php endforeach; ?></select></div><div class="col-md-6"><label class="form-label">Inicio</label><input class="form-control" type="datetime-local" name="inicio" required></div><div class="col-md-6"><label class="form-label">Fin (opcional)</label><input class="form-control" type="datetime-local" name="fin" ></div><div class="col-md-6"><label class="form-label">Estado</label><select name="estado" class="form-select"><option value="programado">Programado</option><option value="en_curso">En curso</option><option value="finalizado">Finalizado</option></select></div><div class="col-12"><button class="btn btn-brand">Guardar</button></div></form></div></div><div class="card"><div class="card-body p-4"><h2 class="h5">Registros</h2><div class="table-responsive"><table class="table table-striped align-middle"><thead><tr><th>ID</th><th>Bus</th><th>Línea</th><th>Inicio</th><th>Fin</th><th>Estado</th></tr></thead><tbody><?php foreach ($rows as $r): ?><tr><td><?=h($r['id_recorrido'])?></td><td><?=h($r['codigo'])?></td><td><?=h($r['linea'])?></td><td><?=h($r['inicio'])?></td><td><?=h($r['fin'])?></td><td><?=h($r['estado'])?></td></tr><?php endforeach; ?><?php if (!$rows): ?><tr><td colspan="6">Aún no hay registros.</td></tr><?php endif; ?></tbody></table></div></div></div></main></body></html>